import { bankAccountsHash, BANK_ACCOUNTS_VERSION } from '../../assets/own-bank-accounts-model.js';
export const bankAccountsIds = Object.freeze({ contract: 'aaaaaaaa-0000-4000-8000-000000000001', registration: 'aaaaaaaa-0000-4000-8000-000000000002', event: 'aaaaaaaa-0000-4000-8000-000000000003', proposal: 'aaaaaaaa-0000-4000-8000-000000000004', key: 'aaaaaaaa-0000-4000-8000-000000000005', account: 'aaaaaaaa-0000-4000-8000-000000000006' });
export const bankAccountsSha = 'a'.repeat(64);
// Invented branch/account blocks, never copied from municipal or bank examples.
export function syntheticCbu(first = '9990001', second = '0000000000001') {
 const digit = (v, weights) => String((10 - weights.reduce((s, w, i) => s + Number(v[i]) * w, 0) % 10) % 10);
 return first + digit(first, [7, 1, 3, 9, 7, 1, 3]) + second + digit(second, [3, 9, 7, 1, 3, 9, 7, 1, 3, 9, 7, 1, 3]);
}
export function syntheticBankAccountsSources() { return { version: bankAccountsSha, contracts: [{ contractId: bankAccountsIds.contract, registrationId: bankAccountsIds.registration, employeeNumber: 'PROPIO-001', name: 'Agente sintético' }] }; }
export function syntheticBankAccountsDefinition() { return { accounts: [{ id: bankAccountsIds.account, contractId: bankAccountsIds.contract, bankLabel: 'Banco sintético', cbu: syntheticCbu(), accountType: null, accountNumber: '00001/02', currency: 'ARS', validFrom: '2026-10-01', validUntil: null, status: 'enabled', documentReference: 'Constancia de titularidad exclusivamente sintética' }] }; }
export function syntheticBankAccountsCommand() { return { command: 'propose', scopeVersion: bankAccountsSha, baseVersion: bankAccountsSha, sourceVersion: bankAccountsSha, proposalId: null, proposalSha256: null, definition: syntheticBankAccountsDefinition(), reason: 'Propuesta bancaria exclusivamente sintética', reviewConfirmed: false }; }
export async function syntheticBankAccountsReceipt() { const body = syntheticBankAccountsCommand(); return { version: BANK_ACCOUNTS_VERSION, eventId: bankAccountsIds.proposal, proposalId: bankAccountsIds.proposal, requestKey: bankAccountsIds.key, requestSha256: await bankAccountsHash(body), body, status: 'pending', revision: 0, configurationVersion: bankAccountsSha, replayed: false, transferGenerated: false, paymentExecuted: false }; }
export async function syntheticBankAccountsDetail() { const body = syntheticBankAccountsCommand(); return { version: BANK_ACCOUNTS_VERSION, scopeVersion: bankAccountsSha, proposal: { id: bankAccountsIds.proposal, requestSha256: await bankAccountsHash(body), baseVersion: bankAccountsSha, sourceVersion: bankAccountsSha, reason: body.reason, createdAt: '2026-10-09T12:00:00Z', authorLabel: 'Preparador sintético', accountCount: 1, canReview: true, status: 'pending', decision: null }, body, baseDefinition: null, sources: syntheticBankAccountsSources(), current: true }; }
export function syntheticBankAccountsBootstrap() { return { version: BANK_ACCOUNTS_VERSION, scopeVersion: bankAccountsSha, sources: syntheticBankAccountsSources(), configuration: { version: bankAccountsSha, revision: 0, definition: null, proposalId: null, approvalId: null }, proposals: [], permissions: { canPropose: true, canReview: false }, complete: true, transferGenerated: false, paymentExecuted: false }; }
